const compradorMap = {
  "001 - Merc. Salgada": "Carlos",
  "004 - Saúde e Estética": "Carlos",
  "006 - Limpeza": "Carlos",
  "010 - Pet Shop": "Carlos",
  "020 - Tabacaria": "Carlos",
  "002 - Merc Doce": "Fernanda",
  "007 - Higiene e Perfumaria": "Fernanda",
  "009 - Bazar": "Fernanda",
  "016 - Cereais": "Fernanda",
  "003 - Bebidas": "Rafael",
  "014 - Açougue": "Rafael",
  "005 - Frios e Laticínios": "Lucas",
  "022 - Peixaria": "Lucas",
  "008 - Horti Fruti": "Beatriz",
  "011 - Restaurante": "Beatriz",
  "012 - Padaria Própria": "Beatriz",
  "015 - Padaria Terceirizada": "Beatriz",
  "021 - Sushi": "Beatriz"
};

const ORDEM_COMPRADORES = ["Beatriz", "Carlos", "Fernanda", "Lucas", "Rafael", "Não Atribuído"];

function normalizar(row) {
  const out = {};
  for (const k of Object.keys(row)) {
    out[String(k).trim()] = row[k];
  }
  return out;
}

function diasDe(data) {
  const m = String(data["ATÉ O VENCIMENTO"] || "").match(/\d+/);
  return m ? parseInt(m[0], 10) : 9999;
}

const stores = [
  { loja: "Loja Centro", rows: $('Ler Loja Centro').all() },
  { loja: "Filial Norte", rows: $('Ler Filial Norte').all() },
  { loja: "Filial Sul", rows: $('Ler Filial Sul').all() }
];

const output = [];

for (const store of stores) {
  let totalRisco = 0;
  const porComprador = {};

  for (const item of store.rows) {
    const data = normalizar(item.json);
    const dias = diasDe(data);
    if (dias <= 15) {
      totalRisco++;
      const merc = String(data["MERCADOLÓGICO"] || "Outros").trim();
      const comprador = compradorMap[merc] || "Não Atribuído";
      porComprador[comprador] = (porComprador[comprador] || 0) + 1;
    }
  }

  let texto = '*[' + store.loja.toUpperCase() + ']* — *' + totalRisco + '* item(ns) em risco (<= 15 dias)\n';
  texto += '---------------------------------------------\n';

  if (totalRisco === 0) {
    texto += 'Nenhum item em risco hoje.';
  } else {
    texto += '*Por comprador:*\n';
    const nomes = Object.keys(porComprador).sort((a, b) => {
      const ia = ORDEM_COMPRADORES.indexOf(a);
      const ib = ORDEM_COMPRADORES.indexOf(b);
      return (ia === -1 ? 999 : ia) - (ib === -1 ? 999 : ib);
    });
    for (const nome of nomes) {
      texto += '- *' + nome + ':* ' + porComprador[nome] + '\n';
    }
    texto += '\nDetalhamento completo no Excel em anexo.';
  }

  output.push({ json: { loja: store.loja, total: totalRisco, mensagem: texto } });
}

return output;

